import { type ChildProcessWithoutNullStreams, spawn } from "node:child_process";
import { createInterface } from "node:readline";

import { TiduError } from "../core/index.js";

export type JsonRpcId = number | string;

export interface JsonRpcProcessLaunch {
  /** Executable that owns the protocol endpoint. */
  command: string;
  /** Fixed arguments generated by a trusted connector adapter. */
  arguments: readonly string[];
  /** Sanitized child-process environment. */
  environment: NodeJS.ProcessEnv;
  /** Working directory exposed to the delegated Agent. */
  workingDirectory?: string;
}

export interface JsonRpcServerRequest {
  /** JSON-RPC request identifier that must be echoed in the response. */
  id: JsonRpcId;
  /** Server-initiated method name. */
  method: string;
  /** Untrusted method parameters supplied by the delegated Agent. */
  params: unknown;
}

export interface JsonRpcNotification {
  /** Server notification method name. */
  method: string;
  /** Untrusted notification payload. */
  params: unknown;
}

export interface JsonRpcClientOptions {
  /** Maximum accepted UTF-8 bytes for one newline-framed message. */
  maximumMessageBytes?: number;
  /** Default request timeout before the pending call is rejected; null disables the local timer. */
  requestTimeoutMilliseconds?: number | null;
  /** Maximum number of concurrent pending client requests. */
  maximumPendingRequests?: number;
  /** Handler for server-initiated permission and interaction requests. */
  onRequest?: (request: JsonRpcServerRequest) => Promise<unknown>;
  /** Handler for streaming and lifecycle notifications. */
  onNotification?: (notification: JsonRpcNotification) => void;
  /** Optional stderr observer; output is never persisted by the transport. */
  onStandardError?: (message: string) => void;
}

export interface JsonRpcClient {
  /** Child process that owns the protocol connection. */
  process: ChildProcessWithoutNullStreams;
  /** Sends one request and waits for the matching response. */
  request: <Result>(method: string, params: unknown, signal?: AbortSignal) => Promise<Result>;
  /** Sends one notification without creating pending state. */
  notify: (method: string, params?: unknown) => void;
  /** Stops accepting work, rejects pending calls, and terminates the child process. */
  close: () => Promise<void>;
}

interface PendingRequest {
  /** Resolves the original client request. */
  resolve: (value: unknown) => void;
  /** Rejects the original client request. */
  reject: (reason: Error) => void;
  /** Clears the request timeout. */
  timeout?: NodeJS.Timeout;
  /** Removes the AbortSignal listener when present. */
  removeAbortListener: () => void;
}

const DEFAULT_LIMITS = Object.freeze({
  maximumMessageBytes: 1_048_576,
  maximumPendingRequests: 128,
  requestTimeoutMilliseconds: 30_000,
});

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isJsonRpcId = (value: unknown): value is JsonRpcId =>
  typeof value === "string" || (typeof value === "number" && Number.isSafeInteger(value));

const toError = (value: unknown, fallback: string): Error => {
  if (isRecord(value) && typeof value.message === "string") {
    return new TiduError("INTERNAL_ERROR", value.message);
  }
  return new TiduError("INTERNAL_ERROR", fallback);
};

export const createStdioJsonRpcClient = (
  launch: JsonRpcProcessLaunch,
  options: JsonRpcClientOptions = {},
): JsonRpcClient => {
  const limits = {
    maximumMessageBytes: options.maximumMessageBytes ?? DEFAULT_LIMITS.maximumMessageBytes,
    maximumPendingRequests: options.maximumPendingRequests ?? DEFAULT_LIMITS.maximumPendingRequests,
    requestTimeoutMilliseconds:
      options.requestTimeoutMilliseconds === undefined
        ? DEFAULT_LIMITS.requestTimeoutMilliseconds
        : options.requestTimeoutMilliseconds,
  };
  const child = spawn(launch.command, [...launch.arguments], {
    cwd: launch.workingDirectory,
    env: launch.environment,
    stdio: ["pipe", "pipe", "pipe"],
  });
  const pendingRequests = new Map<JsonRpcId, PendingRequest>();
  const lines = createInterface({ input: child.stdout, crlfDelay: Number.POSITIVE_INFINITY });
  let nextRequestId = 1;
  let closed = false;
  let closePromise: Promise<void> | undefined;

  const writeMessage = (message: Record<string, unknown>): void => {
    if (closed || child.stdin.destroyed || child.stdin.writableEnded || !child.stdin.writable) {
      throw new TiduError("INTERNAL_ERROR", "Agent protocol connection is closed.");
    }
    const encodedMessage = `${JSON.stringify(message)}\n`;
    if (Buffer.byteLength(encodedMessage) > limits.maximumMessageBytes) {
      throw new TiduError("CONFIGURATION_INVALID", "Agent protocol message exceeds the limit.");
    }
    child.stdin.write(encodedMessage);
  };

  const settlePending = (id: JsonRpcId, settle: (pending: PendingRequest) => void): void => {
    const pending = pendingRequests.get(id);
    if (pending === undefined) {
      return;
    }
    pendingRequests.delete(id);
    if (pending.timeout !== undefined) clearTimeout(pending.timeout);
    pending.removeAbortListener();
    settle(pending);
  };

  const rejectAllPending = (reason: Error): void => {
    for (const id of [...pendingRequests.keys()]) {
      settlePending(id, (pending) => pending.reject(reason));
    }
  };

  const closeConnection = (
    reason: Error = new TiduError("INTERNAL_ERROR", "Agent protocol connection closed."),
  ): Promise<void> => {
    if (closePromise !== undefined) {
      return closePromise;
    }
    closed = true;
    lines.close();
    rejectAllPending(reason);
    if (!child.stdin.destroyed && !child.stdin.writableEnded) {
      child.stdin.end();
    }
    if (child.exitCode !== null || child.signalCode !== null) {
      closePromise = Promise.resolve();
      return closePromise;
    }
    closePromise = new Promise<void>((resolve) => {
      const forceTimer = setTimeout(() => child.kill("SIGKILL"), 1_000);
      child.once("exit", () => {
        clearTimeout(forceTimer);
        resolve();
      });
      child.kill("SIGTERM");
    });
    return closePromise;
  };

  const failConnection = (error: Error): void => {
    if (closed) {
      return;
    }
    void closeConnection(toError(error, "Agent protocol connection failed."));
  };

  const respondToServer = (id: JsonRpcId, result?: unknown, error?: Error): void => {
    if (closed) {
      return;
    }
    try {
      if (error === undefined) {
        writeMessage({ jsonrpc: "2.0", id, result: result ?? null });
        return;
      }
      writeMessage({
        jsonrpc: "2.0",
        id,
        error: { code: -32_000, message: error.message },
      });
    } catch (writeError) {
      failConnection(toError(writeError, "Agent response write failed."));
    }
  };

  lines.on("line", (line) => {
    if (Buffer.byteLength(line) > limits.maximumMessageBytes) {
      void closeConnection();
      return;
    }
    let message: unknown;
    try {
      message = JSON.parse(line) as unknown;
    } catch {
      void closeConnection();
      return;
    }
    if (!isRecord(message)) {
      return;
    }
    if (isJsonRpcId(message.id) && ("result" in message || "error" in message)) {
      settlePending(message.id, (pending) => {
        if ("error" in message && message.error !== undefined) {
          pending.reject(toError(message.error, "Agent protocol request failed."));
        } else {
          pending.resolve(message.result);
        }
      });
      return;
    }
    if (typeof message.method !== "string") {
      return;
    }
    if (isJsonRpcId(message.id)) {
      const serverRequest: JsonRpcServerRequest = {
        id: message.id,
        method: message.method,
        params: message.params,
      };
      if (options.onRequest === undefined) {
        respondToServer(
          message.id,
          undefined,
          new TiduError("CONFIGURATION_INVALID", "Agent request requires explicit handling."),
        );
        return;
      }
      void options.onRequest(serverRequest).then(
        (result) => respondToServer(message.id as JsonRpcId, result),
        (error: unknown) =>
          respondToServer(
            message.id as JsonRpcId,
            undefined,
            toError(error, "Agent request handler failed."),
          ),
      );
      return;
    }
    options.onNotification?.({ method: message.method, params: message.params });
  });

  child.stderr.setEncoding("utf8");
  child.stderr.on("data", (chunk: string) => options.onStandardError?.(chunk));

  child.stdin.on("error", failConnection);
  child.once("error", failConnection);
  child.once("exit", (exitCode, signal) => {
    lines.close();
    closed = true;
    rejectAllPending(
      new TiduError(
        "INTERNAL_ERROR",
        signal === null
          ? `Agent protocol process exited with code ${String(exitCode)}.`
          : `Agent protocol process exited after signal ${signal}.`,
      ),
    );
  });

  const client: JsonRpcClient = {
    process: child,
    request: <Result>(method: string, params: unknown, signal?: AbortSignal): Promise<Result> => {
      if (pendingRequests.size >= limits.maximumPendingRequests) {
        return Promise.reject(
          new TiduError("CONFIGURATION_CONFLICT", "Agent protocol concurrency limit reached."),
        );
      }
      const id = nextRequestId;
      nextRequestId += 1;
      return new Promise<Result>((resolve, reject) => {
        const abort = (): void => {
          settlePending(id, (pending) =>
            pending.reject(new TiduError("INTERNAL_ERROR", "Agent protocol request cancelled.")),
          );
        };
        if (signal?.aborted) {
          reject(new TiduError("INTERNAL_ERROR", "Agent protocol request cancelled."));
          return;
        }
        signal?.addEventListener("abort", abort, { once: true });
        const timeout =
          limits.requestTimeoutMilliseconds === null
            ? undefined
            : setTimeout(() => {
                settlePending(id, (pending) =>
                  pending.reject(
                    new TiduError("INTERNAL_ERROR", "Agent protocol request timed out."),
                  ),
                );
              }, limits.requestTimeoutMilliseconds);
        pendingRequests.set(id, {
          resolve: (value) => resolve(value as Result),
          reject,
          timeout,
          removeAbortListener: () => signal?.removeEventListener("abort", abort),
        });
        try {
          writeMessage({ jsonrpc: "2.0", id, method, params });
        } catch (error) {
          settlePending(id, (pending) => pending.reject(toError(error, "Request write failed.")));
        }
      });
    },
    notify: (method: string, params?: unknown): void => {
      writeMessage({ jsonrpc: "2.0", method, ...(params === undefined ? {} : { params }) });
    },
    close: () => closeConnection(),
  };

  return client;
};
